def get_department(disease_label: str) -> str:
    """Returns the recommended medical department for a given disease label."""
    info = DISEASE_INFO.get(disease_label)
    if info:
        return info.get("department")
    return "Dahiliye (İç Hastalıkları) - Genel Kontrol"

def get_disease_tr_name(disease_label: str) -> str:
    """Returns the Turkish translation for a given disease label."""
    info = DISEASE_INFO.get(disease_label)
    if info:
        return info.get("tr_name")
    return disease_label

def get_disease_urgency(disease_label: str) -> str:
    """Returns the urgency/triage level for a given disease label."""
    info = DISEASE_INFO.get(disease_label)
    if info:
        return info.get("urgency")
    return "Bilmiyoruz (Doktora Başvurun)"
